components.css:
.ds-card { background-color: var(--color-card); border: 3px solid var(--color-border); border-radius: var(--radius-xl); padding: 32px; box-shadow: 2px 2px 0px 0px var(--color-border); transition: all 0.2s cubic-bezier(0.22, 1, 0.36, 1); cursor: pointer; font-family: var(--font-sans); }
.ds-card:hover { transform: translateY(-4px); box-shadow: 8px 8px 0px 0px var(--color-border); }
.ds-card-title { font-size: 24px; font-weight: 900; margin: 0 0 12px 0; color: var(--color-foreground); }
.ds-card-desc { font-size: 16px; font-weight: 500; margin: 0; color: var(--color-muted-foreground); }
